sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 source;
layout(color) uniform half4 target;
uniform float threshold;
uniform float feather;
uniform float choke;
uniform float alpha;
uniform float lockLuminance;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float3 rgb = float3(src.rgb) / float(src.a);
    float d = distance(rgb, float3(source.rgb)) * choke;
    float keep = 1.0 - smoothstep(threshold, threshold + feather + 0.0001, d);
    float light = lockLuminance > 0.5 ? luma(rgb) - luma(float3(source.rgb)) : 0.0;
    float3 swapped = clamp(float3(target.rgb) + light, 0.0, 1.0);
    return half4(half3(mix(rgb, swapped, keep * float(target.a) * clamp(alpha, 0.0, 1.0))) * src.a, src.a);
}
